CREATE PROC [dbo].[ObjectionsInsertUpdate]
(
@Regno varchar(10),
@PaperCode varchar(2),
@VersionCode char(1),
@QuestionNo int,
@KeyAnswer varchar(10),
@ObjectionAns varchar(10),
@Remarks nvarchar(1000),
@FileName varchar(50),
@ObjectionDocs varbinary(Max),
@User varchar(20),
@IPAddress varchar(20)
)
As
BEGIN
BEGIN TRY


if not exists (select * from dbo.Objections where Regno=@Regno and PaperCode=@PaperCode and QuestionNo=@QuestionNo)
BEGIN
--BEGIN TRAN
INSERT INTO Objections(Regno, PaperCode, VersionCode, QuestionNo, KeyAnswer, ObjectionAnswer, Remarks, CreatedUser, CreatedDate,IPAddress)
SELECT @Regno,@PaperCode,@VersionCode,@QuestionNo,@KeyAnswer,@ObjectionAns,@Remarks,@User,GETDATE(),@IPAddress

INSERT INTO ObjectionsDocument (Regno, PaperCode,VersionCode, QuestionNo, FileName, ObjectionDocs, CreatedUser, CreatedDate,IPAddress)
SELECT @Regno,@PaperCode,@VersionCode,@QuestionNo,@FileName,@ObjectionDocs,@User,GETDATE(),@IPAddress
SELECT 'Data saved successfully....'
COMMIT
END
ELSE
BEGIN
DECLARE @I int
SELECT @I=  dateDIFF(MINUTE,CreatedDate,GETDATE()) from Objections where Regno=@Regno and PaperCode=@PaperCode and QuestionNo=@QuestionNo
if @I<14400
BEGIN
UPDATE Objections SET ObjectionAnswer = @ObjectionAns, Remarks = @Remarks, LastModifiedUser= @User , LastModifiedDate =GETDATE(),IPAddress =@IPAddress  where Regno=@Regno and PaperCode=@PaperCode and QuestionNo=@QuestionNo

UPDATE ObjectionsDocument SET [FileName] = @FileName, ObjectionDocs = @ObjectionDocs, LastModifiedUser= @User , LastModifiedDate =GETDATE(),IPAddress =@IPAddress  where Regno=@Regno and PaperCode=@PaperCode and QuestionNo=@QuestionNo
select 'S'
END
ELSE
BEGIN
select 'Objections can not be edited after 24 hours'
END
END
END TRY
BEGIN CATCH
--Rollback;
SELECT ERROR_MESSAGE()
END CATCH
END 

