-- StoredProcedure: dbo.PaymentApplyResult
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE dbo.PaymentApplyResult
    @MerchantOrderNo varchar(50),
    @ResultStatus    varchar(20),
    @SBIReferenceNo  varchar(100) = NULL,
    @PaymentMode     varchar(30) = NULL,
    @PaymentDate     datetime2(0) = NULL,
    @GatewayResponse nvarchar(max) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @ResultStatus NOT IN ('SUCCESS', 'FAILED', 'PENDING')
        THROW 50010, 'Invalid payment result status.', 1;

    DECLARE @PaymentId bigint;

    BEGIN TRAN;

    SELECT @PaymentId = PaymentId
    FROM dbo.PaymentTransactions WITH (UPDLOCK, ROWLOCK)
    WHERE MerchantOrderNo = @MerchantOrderNo AND PaymentStatus = 'PENDING';

    IF @PaymentId IS NOT NULL
    BEGIN
        UPDATE dbo.PaymentTransactions
        SET PaymentStatus             = @ResultStatus,
            SBIReferenceNo            = COALESCE(@SBIReferenceNo, SBIReferenceNo),
            PaymentMode               = COALESCE(@PaymentMode, PaymentMode),
            PaymentDate               = COALESCE(@PaymentDate, PaymentDate),
            GatewayResponse           = COALESCE(@GatewayResponse, GatewayResponse),
            VerificationAttempts      = VerificationAttempts + 1,
            LastVerificationAttemptAt = GETDATE(),
            VerifiedDate              = CASE WHEN @ResultStatus IN ('SUCCESS', 'FAILED') THEN GETDATE() ELSE VerifiedDate END
        WHERE PaymentId = @PaymentId;

        -- A failed payment hands its objections back as drafts so the
        -- candidate can pay again without re-entering them.
        IF @ResultStatus = 'FAILED'
            UPDATE dbo.Objections SET PaymentId = NULL WHERE PaymentId = @PaymentId;
    END

    COMMIT;

    SELECT PaymentStatus FROM dbo.PaymentTransactions WHERE MerchantOrderNo = @MerchantOrderNo;
END

GO

-- StoredProcedure: dbo.PaymentCreate
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE dbo.PaymentCreate
    @RegNo           varchar(10),
    @MerchantOrderNo varchar(50),
    @FeePerObjection decimal(10, 2)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @Resource nvarchar(255) = N'KPSC_PAY_' + @RegNo;
    DECLARE @Count int, @PaymentId bigint, @Amount decimal(10, 2);

    BEGIN TRAN;

    -- One payment at a time per candidate.
    EXEC sp_getapplock @Resource = @Resource, @LockMode = 'Exclusive',
                       @LockOwner = 'Transaction', @LockTimeout = 10000;

    IF EXISTS (SELECT 1 FROM dbo.PaymentTransactions WHERE RegNo = @RegNo AND PaymentStatus = 'PENDING')
    BEGIN
        COMMIT;
        SELECT 'PENDING_EXISTS' AS Result, CAST(NULL AS decimal(10, 2)) AS Amount;
        RETURN;
    END

    IF NOT EXISTS (SELECT 1
                   FROM dbo.Candidate c
                   INNER JOIN dbo.Exam e ON e.ExamCode = LTRIM(RTRIM(c.ExamCode))
                   WHERE c.RegNo = @RegNo
                     AND (e.ObjectionStart IS NULL OR e.ObjectionStart <= GETDATE())
                     AND (e.ObjectionEnd   IS NULL OR e.ObjectionEnd   >= GETDATE()))
    BEGIN
        COMMIT;
        SELECT 'WINDOW_CLOSED' AS Result, CAST(NULL AS decimal(10, 2)) AS Amount;
        RETURN;
    END

    SELECT @Count = COUNT(*) FROM dbo.Objections WHERE Regno = @RegNo AND PaymentId IS NULL;

    IF @Count = 0
    BEGIN
        COMMIT;
        SELECT 'NO_DRAFTS' AS Result, CAST(NULL AS decimal(10, 2)) AS Amount;
        RETURN;
    END

    SET @Amount = @Count * @FeePerObjection;

    INSERT INTO dbo.PaymentTransactions (RegNo, MerchantOrderNo, Amount, PaymentStatus, PaymentInitiatedAt)
    VALUES (@RegNo, @MerchantOrderNo, @Amount, 'PENDING', GETDATE());

    SET @PaymentId = SCOPE_IDENTITY();

    UPDATE dbo.Objections SET PaymentId = @PaymentId WHERE Regno = @RegNo AND PaymentId IS NULL;

    COMMIT;

    SELECT 'OK' AS Result, @Amount AS Amount;
END

GO

-- StoredProcedure: dbo.SBIClaimPendingPayment
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

 CREATE PROCEDURE dbo.SBIClaimPendingPayment
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Now DATETIME2(0) = GETDATE();
    DECLARE @ClaimId UNIQUEIDENTIFIER = NEWID();

    ;WITH PaymentToProcess AS
    (
        SELECT TOP (1) *
        FROM dbo.PaymentTransactions
             WITH (UPDLOCK, READPAST, ROWLOCK)
        WHERE PaymentStatus = 'PENDING'
          AND PaymentInitiatedAt IS NOT NULL
          AND VerificationEligibleAt <= @Now
          AND COALESCE(NextVerificationAt,
                       VerificationEligibleAt) <= @Now
          AND
          (
              VerificationClaimId IS NULL
              OR VerificationLeaseUntil < @Now
          )
        ORDER BY VerificationEligibleAt, PaymentId
    )
    UPDATE PaymentToProcess
    SET
        VerificationClaimId = @ClaimId,
        VerificationLeaseUntil = DATEADD(MINUTE, 5, @Now),
        VerificationAttempts = VerificationAttempts + 1,
        LastVerificationAttemptAt = @Now
    OUTPUT
        inserted.PaymentId,
        inserted.RegNo,
        inserted.MerchantOrderNo,
        inserted.Amount,
        inserted.VerificationAttempts,
        inserted.VerificationClaimId;
END;

GO

-- StoredProcedure: dbo.SBIPaymentMarkInitiated
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE dbo.SBIPaymentMarkInitiated
    @MerchantOrderNo VARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @InitiatedAt DATETIME2(0) = GETDATE();

    UPDATE dbo.PaymentTransactions
    SET
        PaymentInitiatedAt = @InitiatedAt,
        VerificationEligibleAt =
            DATEADD(MINUTE, 20, @InitiatedAt),
        NextVerificationAt =
            DATEADD(MINUTE, 20, @InitiatedAt)
    WHERE MerchantOrderNo = @MerchantOrderNo
      AND PaymentStatus = 'PENDING'
      AND PaymentInitiatedAt IS NULL;

    IF @@ROWCOUNT <> 1
        THROW 50001,
              'Payment transaction could not be marked as initiated.',
              1;
END;

GO

-- StoredProcedure: dbo.SBIUpdateVerificationResult
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE dbo.SBIUpdateVerificationResult
    @PaymentId BIGINT,
    @ClaimId UNIQUEIDENTIFIER,
    @ResultStatus VARCHAR(20),
    @SBIReferenceNo VARCHAR(100) = NULL,
    @PaymentMode VARCHAR(30) = NULL,
    @PaymentDate DATETIME2(0) = NULL,
    @GatewayResponse NVARCHAR(MAX) = NULL,
    @RetryMinutes INT = 5
AS
BEGIN
    SET NOCOUNT ON;

    IF @ResultStatus NOT IN ('SUCCESS', 'FAILED', 'PENDING')
        THROW 50002, 'Invalid verification status.', 1;

    IF @RetryMinutes < 1
        THROW 50003, 'Invalid retry interval.', 1;

    UPDATE dbo.PaymentTransactions
    SET
        PaymentStatus = @ResultStatus,

        SBIReferenceNo =
            COALESCE(@SBIReferenceNo, SBIReferenceNo),

        PaymentMode =
            COALESCE(@PaymentMode, PaymentMode),

        PaymentDate =
            COALESCE(@PaymentDate, PaymentDate),

        GatewayResponse = @GatewayResponse,

        VerifiedDate =
            CASE
                WHEN @ResultStatus IN ('SUCCESS', 'FAILED')
                    THEN GETDATE()
                ELSE VerifiedDate
            END,

        NextVerificationAt =
            CASE
                WHEN @ResultStatus = 'PENDING'
                    THEN DATEADD(MINUTE, @RetryMinutes, GETDATE())
                ELSE NULL
            END,

        VerificationClaimId = NULL,
        VerificationLeaseUntil = NULL

    WHERE PaymentId = @PaymentId
      AND VerificationClaimId = @ClaimId
      AND PaymentStatus = 'PENDING';

    IF @@ROWCOUNT <> 1
        THROW 50004,
              'Payment claim is no longer valid or transaction was already processed.',
              1;
END;

GO

-- StoredProcedure: dbo.UpdateCandidateOTP
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROC [dbo].[UpdateCandidateOTP]
(
@Regno varchar(10),
@OTPHash varbinary(32),
@OTPSalt varbinary(16)
)
As
BEGIN
	BEGIN TRY


	IF EXISTS (SELECT 1 FROM CandidateOTP WHERE RegNo = @RegNo)
        BEGIN
            UPDATE CandidateOTP
            SET OTPHash = @OTPHash,OTPSalt = @OTPSalt,CreatedAt = GETDATE(),ExpiresAt = DATEADD(MINUTE, 5, GETDATE()),LastSentAt = GETDATE(),
                Attempts = 0,IsUsed = 0 WHERE RegNo = @RegNo
			return 1;
        END
        ELSE
        BEGIN
            INSERT INTO CandidateOTP(RegNo, OTPHash, OTPSalt,CreatedAt, ExpiresAt,LastSentAt, Attempts, IsUsed)
            VALUES(@RegNo, @OTPHash, @OTPSalt,GETDATE(),DATEADD(MINUTE, 5, GETDATE()),GETDATE(), 0, 0)

			return 1;
        END
	END TRY
	BEGIN CATCH
		--Rollback;
		--Select ERROR_MESSAGE()
		return 0;
	END CATCH
END 



GO
